evidence.quote:
	use "CCS_UI in Teams/JAR data/wpsmain.dta", clear

	foreach var of varlist communication knowledge_sharing mutual_assistance satisfaction procedual_justice distributive_justice{
		reg `var' level_UI interdependent_team team_size team_length tenure age_group female, r
	}	


*** TABLE 8: Resources Allocation

	gen with_UI = 0 if UI_level_manager == 1
		replace with_UI = 1 if UI_level_manager == 2

	foreach var of varlist q7_5 q7_4 q7_2 q7_3 q7_1 {
		ttest `var', by(with_UI)
	}

univar q7_5 q7_4 q7_2 q7_3 q7_1   , by(with_UI)

/* Build Individual Variables */

use "CCS_UI in Teams/JAR data/ildmain.dta", clear 

	//generate average performance
	egen avg_perf = mean(perf_eval_score_annual), by(ID)
	//generate average performance
	egen avg_tenure = mean(Tenure), by(ID)
	egen avg_female = mean(female), by(ID)
	egen avg_age = mean(age), by(ID)
	//generate top performer dummy
	sort ID year project_id
	egen avg_team_top_performer = mean(team_top_performer), by(ID)
	//generate turnover variable 
	qui xtset ID year
		gen turnover_t1 = f.turnover

save "CCS_UI in Teams/JAR data/ildmain.dta", replace
